insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Infração de medida sanitária preventiva: infringir determinação do poder público destinada a impedir introdução ou propagação de doença contagiosa. Pena: detenção de um mês a um ano e multa. A pena é aumentada de um terço se o agente é funcionário da saúde pública ou exerce a profissão de médico, farmacêutico, dentista ou enfermeiro.', '["Infringir determinação do poder público contra doença contagiosa.","Detenção de um mês a um ano e multa.","Parágrafo único: aumento de um terço (funcionário da saúde pública, médico, farmacêutico, dentista ou enfermeiro)."]'::jsonb, '["Norma penal em branco: depende da determinação do poder público."]'::jsonb, 'Descumprir quarentena determinada pela autoridade sanitária.', '["Assertiva que dispensa a existência de determinação do poder público erra."]'::jsonb, '[{"termo":"Norma penal em branco","significado":"Norma cuja descrição depende de complementação por outra norma."}]'::jsonb, '["Art. 267"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-268'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

