insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Envenenamento de água potável ou de substância alimentícia ou medicinal: envenenar água potável, de uso comum ou particular, ou substância alimentícia ou medicinal destinada a consumo. Pena: reclusão de dez a quinze anos. Está sujeito à mesma pena quem entrega a consumo ou tem em depósito, para o fim de ser distribuída, a água ou a substância envenenada. Se culposo: detenção de seis meses a dois anos.', '["Envenenar água potável (comum ou particular) ou substância alimentícia ou medicinal.","Reclusão de dez a quinze anos.","§1º: entregar a consumo ou ter em depósito para distribuir.","§2º: culposo: detenção de seis meses a dois anos."]'::jsonb, '["Crime hediondo (pena fixada pela Lei dos Crimes Hediondos)."]'::jsonb, 'Envenenar o reservatório de água de um bairro.', '["Assertiva que fixa pena de detenção para o caput do art. 270 erra: é reclusão de dez a quinze anos."]'::jsonb, '[]'::jsonb, '["Art. 271"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-270'
