insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Corrupção ou poluição de água potável: corromper ou poluir água potável, de uso comum ou particular, tornando-a imprópria para consumo ou nociva à saúde. Pena: reclusão de dois a cinco anos. Se culposo: detenção de dois meses a um ano.', '["Corromper ou poluir água potável tornando-a imprópria ou nociva.","Reclusão de dois a cinco anos.","Culposo: detenção de dois meses a um ano."]'::jsonb, '["Diferença para o art. 270: aqui a água é corrompida ou poluída; lá, envenenada."]'::jsonb, 'Despejar substância que torna imprópria a água potável de uso comum.', '["Assertiva que confunde poluição com envenenamento erra: o art. 270 trata do envenenamento."]'::jsonb, '[]'::jsonb, '["Art. 270"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-271'
