insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Falsificação, corrupção, adulteração ou alteração de substância ou produtos alimentícios: corromper, adulterar, falsificar ou alterar substância ou produto alimentício destinado a consumo, tornando-o nocivo à saúde ou reduzindo-lhe o valor nutritivo. Pena: reclusão de 4 a 8 anos e multa. Incorre nas penas quem fabrica, vende, expõe à venda, importa, tem em depósito para vender ou, de qualquer forma, distribui ou entrega a consumo o produto falsificado, corrompido ou adulterado. Aplica-se também a bebidas, com ou sem teor alcoólico. Se culposo: detenção de 1 a 2 anos e multa.', '["Corromper, adulterar, falsificar ou alterar produto alimentício, tornando-o nocivo ou reduzindo-lhe o valor nutritivo.","Reclusão de 4 a 8 anos e multa.","§1º-A: fabricar, vender, expor à venda, importar, ter em depósito, distribuir ou entregar a consumo.","§1º: aplica-se a bebidas, com ou sem teor alcoólico.","§2º: culposo: detenção de 1 a 2 anos e multa."]'::jsonb, '["Inclui bebidas, com ou sem álcool."]'::jsonb, 'Adulterar alimento para vender, reduzindo seu valor nutritivo.', '["Assertiva que exclui as bebidas do art. 272 erra: o §1º as inclui."]'::jsonb, '[]'::jsonb, '["Art. 273"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-272'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Falsificação, corrupção, adulteração ou alteração de produto destinado a fins terapêuticos ou medicinais: falsificar, corromper, adulterar ou alterar produto destinado a fins terapêuticos ou medicinais. Pena: reclusão de 10 a 15 anos e multa. Nas mesmas penas incorre quem importa, vende, expõe à venda, tem em depósito para vender ou, de qualquer forma, distribui ou entrega a consumo o produto falsificado, corrompido, adulterado ou alterado. Incluem-se entre os produtos os medicamentos, as matérias-primas, os insumos farmacêuticos, os cosméticos, os saneantes e os de uso em diagnóstico. Também responde quem pratica as ações do §1º em relação a produtos sem registro, quando exigível, no órgão de vigilância sanitária competente, em desacordo com a fórmula do registro ou sem as características de identidade e qualidade admitidas para a comercialização, entre outras hipóteses do dispositivo.', '["Falsificar, corromper, adulterar ou alterar produto terapêutico ou medicinal.","Reclusão de 10 a 15 anos e multa.","§1º: importar, vender, expor à venda, ter em depósito, distribuir ou entregar a consumo.","§1º-A: medicamentos, matérias-primas, insumos farmacêuticos, cosméticos, saneantes e produtos de diagnóstico.","§1º-B: produtos sem registro, em desacordo com a fórmula, sem identidade e qualidade, entre outros."]'::jsonb, '["A pena é muito severa; confira no texto integral as hipóteses do §1º-B."]'::jsonb, 'Vender medicamento sem o registro exigível no órgão de vigilância sanitária.', '["Assertiva que exclui cosméticos e saneantes do rol do art. 273 erra: o §1º-A os inclui."]'::jsonb, '[]'::jsonb, '["Art. 272","Art. 274"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-273'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Emprego de processo proibido ou de substância não permitida: empregar, no fabrico de produto destinado a consumo, revestimento, gaseificação artificial, matéria corante, substância aromática, anti-séptica, conservadora ou qualquer outra não expressamente permitida pela legislação sanitária. Pena: reclusão de 1 a 5 anos e multa.', '["Empregar substância não permitida pela legislação sanitária no fabrico de produto destinado a consumo.","Reclusão de 1 a 5 anos e multa."]'::jsonb, '["Norma penal em branco: depende da legislação sanitária."]'::jsonb, 'Usar corante não permitido pela legislação sanitária em alimento.', '["Assertiva que dispensa a referência à legislação sanitária erra."]'::jsonb, '[]'::jsonb, '["Art. 275","Art. 276"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-274'
