insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Outras substâncias nocivas à saúde pública: fabricar, vender, expor à venda, ter em depósito para vender ou, de qualquer forma, entregar a consumo coisa ou substância nociva à saúde, ainda que não destinada à alimentação ou a fim medicinal. Pena: detenção de um a três anos e multa. Se culposo: detenção de dois meses a um ano.', '["Fabricar, vender, expor à venda, ter em depósito ou entregar a consumo coisa nociva à saúde.","Ainda que não destinada à alimentação ou a fim medicinal.","Detenção de um a três anos e multa.","Culposo: detenção de dois meses a um ano."]'::jsonb, '["Tipo residual: não exige finalidade alimentar ou medicinal."]'::jsonb, 'Vender produto de uso doméstico sabidamente nocivo à saúde.', '["Assertiva que restringe o art. 278 a alimentos e remédios erra."]'::jsonb, '[]'::jsonb, '["Art. 272","Art. 273"]'::jsonb, 'under_review', 'claude'
