insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Exercício ilegal da medicina, arte dentária ou farmacêutica: exercer, ainda que a título gratuito, a profissão de médico, médico veterinário, dentista ou farmacêutico, sem autorização legal ou excedendo-lhe os limites. Pena: detenção de 6 meses a 2 anos. Com fim de lucro, aplica-se também multa. Se resulta lesão corporal grave ou gravíssima, responde também pelo art. 129, §§ 1º e 2º; se resulta morte, responde também por homicídio (art. 121); se resulta lesão ou morte de animal, responde também pelo art. 32 da Lei nº 9.605, de 1998. Incorre no caput quem exerce a profissão durante a suspensão ou após o cancelamento da habilitação ou do registro profissional.', '["Exercer a profissão sem autorização legal ou excedendo os limites, ainda que gratuitamente.","Detenção de 6 meses a 2 anos.","§1º: fim de lucro: também multa.","§2º e §3º: lesão grave ou gravíssima e morte geram concurso com os crimes dos arts. 129 e 121.","§4º: lesão ou morte de animal: também o art. 32 da Lei nº 9.605, de 1998.","§5º: exercício durante suspensão ou após cancelamento do registro."]'::jsonb, '["Vale ainda que a título GRATUITO.","A redação é recente (2026)."]'::jsonb, 'Pessoa sem diploma atende pacientes como médico, mesmo sem cobrar.', '["Assertiva que exige cobrança de valores para configurar o art. 282 erra: basta exercer sem autorização, ainda que gratuitamente."]'::jsonb, '[]'::jsonb, '["Art. 121","Art. 129","Art. 283","Art. 284"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-282'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Charlatanismo: inculcar ou anunciar cura por meio secreto ou infalível. Pena: detenção de três meses a um ano e multa.', '["Inculcar ou anunciar cura por meio secreto ou infalível.","Detenção de três meses a um ano e multa."]'::jsonb, '["Não confundir com o curandeirismo (art. 284)."]'::jsonb, 'Anunciar uma fórmula secreta que cura qualquer doença.', '["Assertiva que exige o ato de tratar o paciente no charlatanismo erra: basta inculcar ou anunciar a cura."]'::jsonb, '[{"termo":"Charlatanismo","significado":"Anunciar cura por meio secreto ou infalível."}]'::jsonb, '["Art. 284"]'::jsonb, 'under_review', 'claude'
