insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Curandeirismo: exercer o curandeirismo prescrevendo, ministrando ou aplicando, habitualmente, qualquer substância; usando gestos, palavras ou qualquer outro meio; ou fazendo diagnósticos. Pena: detenção de seis meses a dois anos. Se há remuneração, também multa.', '["Prescrever, ministrar ou aplicar habitualmente qualquer substância.","Usar gestos, palavras ou outro meio.","Fazer diagnósticos.","Detenção de seis meses a dois anos.","Remuneração: também multa."]'::jsonb, '["A habitualidade consta do inciso I."]'::jsonb, 'Pessoa sem formação aplica habitualmente substâncias para curar doenças.', '["Assertiva que exige remuneração para configurar o curandeirismo erra: ela só acrescenta multa."]'::jsonb, '[]'::jsonb, '["Art. 282","Art. 283"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-284'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Forma qualificada: aplica-se o disposto no art. 258 aos crimes previstos neste Capítulo, salvo quanto ao definido no art. 267.', '["Aplica-se o art. 258 aos crimes do Capítulo.","Exceção: o crime do art. 267 (epidemia)."]'::jsonb, '["A exceção é o art. 267."]'::jsonb, 'O resultado morte em crime do Capítulo agrava a pena nos termos do art. 258.', '["Assertiva que aplica o art. 258 também ao crime do art. 267, por força do art. 285, erra."]'::jsonb, '[]'::jsonb, '["Art. 258","Art. 267"]'::jsonb, 'under_review', 'claude'
