insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Incitação ao crime: incitar, publicamente, a prática de crime. Pena: detenção de três a seis meses, ou multa. Incorre na mesma pena quem incita, publicamente, animosidade entre as Forças Armadas, ou delas contra os poderes constitucionais, as instituições civis ou a sociedade.', '["Incitar publicamente a prática de crime.","Detenção de três a seis meses, ou multa.","Parágrafo único: incitar animosidade entre as Forças Armadas, ou delas contra poderes, instituições civis ou a sociedade."]'::jsonb, '["O incitamento deve ser PÚBLICO.","Crime de menor potencial ofensivo."]'::jsonb, 'Em praça, incitar a multidão a praticar saques.', '["Assertiva que dispensa a publicidade da incitação erra."]'::jsonb, '[]'::jsonb, '["Art. 287"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-286'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Apologia de crime ou criminoso: fazer, publicamente, apologia de fato criminoso ou de autor de crime. Pena: detenção de três a seis meses, ou multa.', '["Fazer publicamente apologia de fato criminoso ou de autor de crime.","Detenção de três a seis meses, ou multa."]'::jsonb, '["Diferença para o art. 286: aqui há ELOGIO; lá, INCITAÇÃO."]'::jsonb, 'Em ato público, exaltar um crime já ocorrido e seu autor.', '["Assertiva que confunde apologia com incitação erra."]'::jsonb, '[]'::jsonb, '["Art. 286"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-287'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Associação criminosa: associarem-se 3 ou mais pessoas, para o fim específico de cometer crimes. Pena: reclusão de 1 a 3 anos. A pena aumenta-se até a metade se a associação é armada ou se há participação de criança ou adolescente. Incorre na pena do caput quem, de qualquer modo, solicitar ou contratar o cometimento de crime a integrante de associação criminosa, independentemente da aplicação da pena do crime solicitado ou contratado.', '["Associação de 3 ou mais pessoas.","Fim específico de cometer crimes.","Reclusão de 1 a 3 anos.","§1º: aumento até a metade (armada ou com criança ou adolescente).","§2º: quem solicita ou contrata crime a integrante da associação."]'::jsonb, '["O mínimo é de 3 pessoas.","Exige a finalidade de cometer crimes e permanência; não basta o concurso eventual."]'::jsonb, 'Quatro pessoas se organizam para praticar furtos em série.', '["Assertiva que fixa em duas pessoas o mínimo da associação criminosa erra: são 3 ou mais."]'::jsonb, '[]'::jsonb, '["Art. 288-A","Lei nº 12.850, de 2013"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-288'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Constituição de milícia privada: constituir, organizar, integrar, manter ou custear organização paramilitar, milícia particular, grupo ou esquadrão com a finalidade de praticar qualquer dos crimes previstos neste Código. Pena: reclusão de 4 a 8 anos.', '["Constituir, organizar, integrar, manter ou custear organização paramilitar, milícia, grupo ou esquadrão.","Finalidade de praticar crimes previstos no Código Penal.","Reclusão de 4 a 8 anos."]'::jsonb, '["Pena maior que a da associação criminosa."]'::jsonb, 'Grupo armado se organiza como milícia para praticar crimes em um bairro.', '["Assertiva que fixa pena de detenção para o art. 288-A erra: é reclusão de 4 a 8 anos."]'::jsonb, '[]'::jsonb, '["Art. 288"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-288-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Moeda falsa: falsificar, fabricando-a ou alterando-a, moeda metálica ou papel-moeda de curso legal no país ou no estrangeiro. Pena: reclusão de três a doze anos e multa. Mesma pena a quem, por conta própria ou alheia, importa ou exporta, adquire, vende, troca, cede, empresta, guarda ou introduz na circulação moeda falsa. Quem, tendo recebido de boa-fé, restitui à circulação depois de conhecer a falsidade: detenção de seis meses a dois anos e multa. Funcionário público, diretor, gerente ou fiscal de banco de emissão que fabrica, emite ou autoriza a fabricação ou emissão de moeda com título ou peso inferior ao legal ou de papel-moeda em quantidade superior à autorizada: reclusão de três a quinze anos e multa. Nas mesmas penas quem desvia e faz circular moeda não autorizada.', '["Caput: falsificar moeda (fabricar ou alterar).","Reclusão de três a doze anos e multa.","§1º: importar, exportar, adquirir, vender, trocar, ceder, emprestar, guardar ou introduzir na circulação.","§2º: recebeu de boa-fé e restituiu à circulação: detenção de seis meses a dois anos e multa.","§3º: funcionário ou diretor de banco de emissão: reclusão de três a quinze anos e multa.","§4º: desviar e fazer circular moeda não autorizada."]'::jsonb, '["Competência da Justiça Federal.","Boa-fé inicial reduz a pena (§2º)."]'::jsonb, 'Quem recebeu nota falsa de boa-fé e depois a repassa, já ciente da falsidade, comete a forma do §2º.', '["Assertiva que aplica a pena do caput ao §2º erra: é detenção de seis meses a dois anos e multa."]'::jsonb, '[]'::jsonb, '["Art. 290","Art. 291"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-289'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Crimes assimilados ao de moeda falsa: formar cédula, nota ou bilhete representativo de moeda com fragmentos de cédulas verdadeiras; suprimir, em nota recolhida, para restituí-la à circulação, sinal indicativo de sua inutilização; restituir à circulação cédula em tais condições, ou já recolhida para inutilização. Pena: reclusão de dois a oito anos e multa. O máximo da reclusão é elevado a doze anos e multa, se o crime é cometido por funcionário que trabalha na repartição onde o dinheiro se achava recolhido, ou nela tem fácil ingresso.', '["Formar cédula com fragmentos de cédulas verdadeiras.","Suprimir sinal de inutilização para devolver à circulação.","Restituir à circulação cédula nessas condições.","Reclusão de dois a oito anos e multa.","Parágrafo único: funcionário da repartição: máximo elevado a doze anos."]'::jsonb, '["Aqui o aumento é só do MÁXIMO da pena."]'::jsonb, 'Funcionário da repartição de recolhimento devolve à circulação notas já recolhidas.', '["Assertiva que eleva também o mínimo da pena no parágrafo único erra: só o máximo é elevado."]'::jsonb, '[]'::jsonb, '["Art. 289"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-290'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Petrechos para falsificação de moeda: fabricar, adquirir, fornecer, a título oneroso ou gratuito, possuir ou guardar maquinismo, aparelho, instrumento ou qualquer objeto especialmente destinado à falsificação de moeda. Pena: reclusão de dois a seis anos e multa.', '["Fabricar, adquirir, fornecer, possuir ou guardar maquinismo ou objeto para falsificar moeda.","Reclusão de dois a seis anos e multa."]'::jsonb, '["O objeto deve ser ESPECIALMENTE destinado à falsificação."]'::jsonb, 'Guardar máquina própria para falsificar notas.', '["Assertiva que aplica o art. 291 a qualquer objeto, ainda que de uso comum, erra: é especialmente destinado à falsificação."]'::jsonb, '[]'::jsonb, '["Art. 289"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-291'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Emissão de título ao portador sem permissão legal: emitir, sem permissão legal, nota, bilhete, ficha, vale ou título que contenha promessa de pagamento em dinheiro ao portador ou a que falte indicação do nome da pessoa a quem deva ser pago. Pena: detenção de um a seis meses, ou multa. Quem recebe ou utiliza como dinheiro esses documentos: detenção de quinze dias a três meses, ou multa.', '["Emitir, sem permissão legal, documento com promessa de pagamento ao portador.","Detenção de um a seis meses, ou multa.","Parágrafo único: receber ou utilizar como dinheiro: detenção de quinze dias a três meses, ou multa."]'::jsonb, '["O parágrafo único pune quem RECEBE ou UTILIZA, com pena menor."]'::jsonb, 'Emitir vale ao portador, sem autorização legal, para circular como dinheiro.', '["Assertiva que aplica ao usuário do documento a mesma pena do emissor erra."]'::jsonb, '[]'::jsonb, '["Art. 289"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-292'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Falsificação de papéis públicos: falsificar, fabricando-os ou alterando-os, selo destinado a controle tributário, papel selado ou qualquer papel de emissão legal destinado à arrecadação de tributo; papel de crédito público que não seja moeda de curso legal; vale postal; cautela de penhor, caderneta de depósito de caixa econômica ou de outro estabelecimento mantido por entidade de direito público; talão, recibo, guia, alvará ou outro documento relativo a arrecadação de rendas públicas ou a depósito ou caução por que o poder público seja responsável; bilhete, passe ou conhecimento de empresa de transporte administrada pela União, por Estado ou por Município. Pena: reclusão de dois a oito anos e multa. Na mesma pena quem usa, guarda, possui ou detém qualquer dos papéis falsificados e quem pratica as condutas do §1º, II e III, relativas a selo falsificado destinado a controle tributário.', '["Falsificar selo de controle tributário, papel selado, papel de crédito público, vale postal, cautela de penhor, documentos de arrecadação pública e bilhetes de transporte público.","Reclusão de dois a oito anos e multa.","§1º: uso, guarda, posse ou detenção dos papéis falsificados e condutas de circulação de selo falsificado."]'::jsonb, '["Rol específico de papéis públicos."]'::jsonb, 'Falsificar selo destinado a controle tributário.', '["Assertiva que aplica o art. 293 à falsificação de documento particular erra."]'::jsonb, '[]'::jsonb, '["Art. 294","Art. 295"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-293'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Petrechos de falsificação: fabricar, adquirir, fornecer, possuir ou guardar objeto especialmente destinado à falsificação de qualquer dos papéis referidos no artigo anterior. Pena: reclusão de um a três anos e multa.', '["Fabricar, adquirir, fornecer, possuir ou guardar objeto especialmente destinado à falsificação dos papéis do art. 293.","Reclusão de um a três anos e multa."]'::jsonb, '["Refere-se aos papéis do art. 293."]'::jsonb, 'Guardar equipamento próprio para falsificar selo de controle tributário.', '["Assertiva que aplica o art. 294 à falsificação de moeda erra: para ela vale o art. 291."]'::jsonb, '[]'::jsonb, '["Art. 291","Art. 293"]'::jsonb, 'under_review', 'claude'
