insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Falsificação do selo ou sinal público: falsificar, fabricando-os ou alterando-os, selo público destinado a autenticar atos oficiais da União, de Estado ou de Município; ou selo ou sinal atribuído por lei a entidade de direito público, ou a autoridade, ou sinal público de tabelião. Pena: reclusão de dois a seis anos e multa. Incorre nas mesmas penas quem faz uso do selo ou sinal falsificado; quem utiliza indevidamente o selo ou sinal verdadeiro em prejuízo de outrem ou em proveito próprio ou alheio; e quem altera, falsifica ou faz uso indevido de marcas, logotipos, siglas ou símbolos identificadores de órgãos ou entidades da Administração Pública. Se o agente é funcionário público e se prevalece do cargo, aumenta-se a pena de sexta parte.', '["Falsificar selo público ou sinal de entidade, autoridade ou tabelião.","Reclusão de dois a seis anos e multa.","§1º: uso do selo falsificado; uso indevido do verdadeiro; marcas e símbolos da Administração.","§2º: funcionário público: aumento de sexta parte."]'::jsonb, '["Inclui o uso indevido de selo VERDADEIRO."]'::jsonb, 'Usar sem autorização selo verdadeiro de um órgão público em proveito próprio.', '["Assertiva que exclui o uso indevido do selo verdadeiro do art. 296 erra."]'::jsonb, '[]'::jsonb, '["Art. 297"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-296'
