insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Falsificação de documento público: falsificar, no todo ou em parte, documento público, ou alterar documento público verdadeiro. Pena: reclusão de dois a seis anos e multa. Funcionário público que se prevalece do cargo: aumento de sexta parte. Equiparam-se a documento público o emanado de entidade paraestatal, o título ao portador ou transmissível por endosso, as ações de sociedade comercial, os livros mercantis e o testamento particular. Nas mesmas penas incorre quem insere ou faz inserir em folha de pagamento ou documento destinado à previdência social pessoa que não possua a qualidade de segurado obrigatório; na CTPS ou em documento que deva produzir efeito perante a previdência, declaração falsa ou diversa; ou em documento contábil ou relacionado com as obrigações da empresa perante a previdência, declaração falsa ou diversa.', '["Falsificar ou alterar documento público.","Reclusão de dois a seis anos e multa.","§1º: funcionário público prevalecendo-se do cargo: aumento de sexta parte.","§2º: equiparados a documento público (paraestatal, título ao portador, ações, livros mercantis, testamento particular).","§3º: inserções falsas em documentos previdenciários."]'::jsonb, '["Falsidade MATERIAL (forma do documento).","Testamento particular é equiparado a documento público."]'::jsonb, 'Alterar uma carteira de identidade verdadeira.', '["Assertiva que considera documento particular o testamento particular, para efeitos penais, erra: o §2º o equipara a público."]'::jsonb, '[]'::jsonb, '["Art. 298","Art. 299","Art. 304"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-297'
