insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Falsificação de documento particular: falsificar, no todo ou em parte, documento particular ou alterar documento particular verdadeiro. Pena: reclusão de um a cinco anos e multa. Para esses fins, equipara-se a documento particular o cartão de crédito ou débito.', '["Falsificar ou alterar documento particular.","Reclusão de um a cinco anos e multa.","Parágrafo único: cartão de crédito ou débito equipara-se a documento particular."]'::jsonb, '["Cartão de crédito ou débito = documento particular."]'::jsonb, 'Clonar cartão de crédito de terceiro.', '["Assertiva que considera o cartão de crédito documento público erra: equipara-se a particular."]'::jsonb, '[]'::jsonb, '["Art. 297","Art. 304"]'::jsonb, 'under_review', 'claude'
