insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Falsidade ideológica: omitir, em documento público ou particular, declaração que dele devia constar, ou nele inserir ou fazer inserir declaração falsa ou diversa da que devia ser escrita, com o fim de prejudicar direito, criar obrigação ou alterar a verdade sobre fato juridicamente relevante. Pena: reclusão de um a cinco anos e multa, se o documento é público, e reclusão de um a três anos e multa, se é particular. Se o agente é funcionário público e se prevalece do cargo, ou se a falsificação ou alteração é de assentamento de registro civil, aumenta-se a pena de sexta parte.', '["Omitir ou inserir declaração falsa em documento.","Fim específico: prejudicar direito, criar obrigação ou alterar a verdade sobre fato relevante.","Documento público: reclusão de um a cinco anos e multa.","Documento particular: reclusão de um a três anos e multa.","Parágrafo único: funcionário público ou registro civil: aumento de sexta parte."]'::jsonb, '["Falsidade IDEOLÓGICA: o documento é formalmente verdadeiro, mas o CONTEÚDO é falso.","Exige dolo específico."]'::jsonb, 'Inserir em escritura pública declaração falsa para prejudicar direito de terceiro.', '["Assertiva que considera material a falsidade em que o documento é formalmente autêntico, mas com conteúdo falso, erra: é ideológica."]'::jsonb, '[{"termo":"Falsidade ideológica","significado":"Documento formalmente verdadeiro com conteúdo falso."}]'::jsonb, '["Art. 297","Art. 304"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-299'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

