select u.id, u.content_sha256, 'Falso reconhecimento de firma ou letra: reconhecer, como verdadeira, no exercício de função pública, firma ou letra que o não seja. Pena: reclusão de um a cinco anos e multa, se o documento é público; e de um a três anos e multa, se o documento é particular.', '["Reconhecer como verdadeira firma ou letra falsa, no exercício de função pública.","Documento público: reclusão de um a cinco anos e multa.","Documento particular: reclusão de um a três anos e multa."]'::jsonb, '["Crime PRÓPRIO: o agente exerce função pública."]'::jsonb, 'Tabelião reconhece como verdadeira uma firma que sabe falsa.', '["Assertiva que admite como sujeito ativo qualquer pessoa, sem função pública, erra."]'::jsonb, '[]'::jsonb, '["Art. 299"]'::jsonb, 'under_review', 'claude'
