insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Certidão ou atestado ideologicamente falso: atestar ou certificar falsamente, em razão de função pública, fato ou circunstância que habilite alguém a obter cargo público, isenção de ônus ou de serviço de caráter público, ou qualquer outra vantagem. Pena: detenção de dois meses a um ano. Falsidade material de atestado ou certidão (§1º): falsificar, no todo ou em parte, atestado ou certidão, ou alterar o teor de atestado ou certidão verdadeiros, para o mesmo fim: detenção de três meses a dois anos. Com o fim de lucro, aplica-se também multa.', '["Caput: atestar ou certificar falsamente, em razão de função pública.","Detenção de dois meses a um ano.","§1º: falsificar ou alterar atestado ou certidão: detenção de três meses a dois anos.","§2º: fim de lucro: também multa."]'::jsonb, '["O caput é ideológico, e o §1º é material."]'::jsonb, 'Servidor atesta falsamente fato que habilita alguém a obter cargo público.', '["Assertiva que inverte as naturezas do caput (ideológica) e do §1º (material) erra."]'::jsonb, '[]'::jsonb, '["Art. 302"]'::jsonb, 'under_review', 'claude'
