select u.id, u.content_sha256, 'Reprodução ou adulteração de selo ou peça filatélica: reproduzir ou alterar selo ou peça filatélica que tenha valor para coleção, salvo quando a reprodução ou a alteração está visivelmente anotada na face ou no verso do selo ou peça. Pena: detenção de um a três anos e multa. Na mesma pena quem, para fins de comércio, faz uso do selo ou peça filatélica.', '["Reproduzir ou alterar selo ou peça filatélica de valor para coleção.","Detenção de um a três anos e multa.","Exceção: reprodução ou alteração visivelmente anotada.","Parágrafo único: uso para fins de comércio."]'::jsonb, '["Não há crime se a reprodução ou alteração vem visivelmente anotada."]'::jsonb, 'Reproduzir selo raro sem anotar a reprodução.', '["Assertiva que pune a reprodução visivelmente anotada no selo erra."]'::jsonb, '[]'::jsonb, '["Art. 293"]'::jsonb, 'under_review', 'claude'
