select u.id, u.content_sha256, 'Falsificação do sinal empregado no contraste de metal precioso ou na fiscalização alfandegária: falsificar, fabricando-o ou alterando-o, marca ou sinal empregado pelo poder público no contraste de metal precioso ou na fiscalização alfandegária, ou usar marca ou sinal dessa natureza, falsificado por outrem. Pena: reclusão de dois a seis anos e multa. Se a marca ou sinal falsificado é o de fiscalização sanitária, ou para autenticar ou encerrar determinados objetos, ou comprovar o cumprimento de formalidade legal: reclusão ou detenção de um a três anos e multa.', '["Falsificar marca ou sinal de contraste de metal precioso ou de fiscalização alfandegária, ou usar o sinal falsificado por outrem.","Reclusão de dois a seis anos e multa.","Parágrafo único: fiscalização sanitária, autenticação de objetos ou formalidade legal: reclusão ou detenção de um a três anos e multa."]'::jsonb, '["O parágrafo único tem pena mais branda."]'::jsonb, 'Falsificar sinal de fiscalização sanitária.', '["Assertiva que aplica a mesma pena do caput ao parágrafo único erra."]'::jsonb, '[]'::jsonb, '["Art. 296"]'::jsonb, 'under_review', 'claude'
