select u.id, u.content_sha256, 'Falsa identidade: atribuir-se ou atribuir a terceiro falsa identidade para obter vantagem, em proveito próprio ou alheio, ou para causar dano a outrem. Pena: detenção de três meses a um ano, ou multa, se o fato não constitui elemento de crime mais grave.', '["Atribuir-se ou atribuir a terceiro falsa identidade.","Fim de obter vantagem ou causar dano.","Detenção de três meses a um ano, ou multa.","Subsidiário."]'::jsonb, '["Exige finalidade de vantagem ou dano.","Crime subsidiário."]'::jsonb, 'Apresentar-se com nome de outra pessoa para obter vantagem.', '["Assertiva que dispensa a finalidade de vantagem ou dano no art. 307 erra."]'::jsonb, '[]'::jsonb, '["Art. 308"]'::jsonb, 'under_review', 'claude'
