select u.id, u.content_sha256, 'Uso de documento de identidade alheia: usar, como próprio, passaporte, título de eleitor, caderneta de reservista ou qualquer documento de identidade alheia ou ceder a outrem, para que dele se utilize, documento dessa natureza, próprio ou de terceiro. Pena: detenção de quatro meses a dois anos e multa, se o fato não constitui elemento de crime mais grave.', '["Usar como próprio documento de identidade alheia.","Ou ceder a outrem documento de identidade, próprio ou de terceiro, para uso.","Detenção de quatro meses a dois anos e multa.","Subsidiário."]'::jsonb, '["Não confundir com a falsa identidade (art. 307)."]'::jsonb, 'Usar, como próprio, o passaporte de outra pessoa.', '["Assertiva que torna o crime do art. 308 não subsidiário erra."]'::jsonb, '[]'::jsonb, '["Art. 307"]'::jsonb, 'under_review', 'claude'
