insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Adulteração de sinal identificador de veículo automotor: adulterar, remarcar ou suprimir número de chassi, monobloco, motor, placa de identificação, ou qualquer sinal identificador de veículo automotor, elétrico, híbrido, de reboque, de semirreboque ou de suas combinações, bem como de seus componentes ou equipamentos, sem autorização do órgão competente. Pena: reclusão de três a seis anos e multa. Se o agente comete o crime no exercício da função pública ou em razão dela, a pena é aumentada de um terço. Incorrem nas mesmas penas o funcionário público que contribui para o licenciamento ou registro do veículo remarcado ou adulterado, fornecendo indevidamente material ou informação oficial, e quem adquire, recebe, transporta, oculta, mantém em depósito, fabrica, fornece, possui ou guarda maquinismo ou objeto especialmente destinado à falsificação ou adulteração, entre outras condutas previstas no dispositivo.', '["Adulterar, remarcar ou suprimir sinal identificador de veículo, seus componentes ou equipamentos, sem autorização.","Reclusão de três a seis anos e multa.","§1º: função pública ou em razão dela: aumento de um terço.","§2º: funcionário que contribui para o licenciamento; quem fornece ou guarda maquinismo para a adulteração, entre outras condutas."]'::jsonb, '["Inclui placa, chassi, motor e demais sinais.","A redação foi alterada em 2023."]'::jsonb, 'Remarcar número de chassi de veículo sem autorização do órgão competente.', '["Assertiva que aplica o art. 311 apenas a veículos de combustão erra: abrange automotor, elétrico, híbrido, reboque e semirreboque."]'::jsonb, '[]'::jsonb, '["Art. 297"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-311'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fraudes em certames de interesse público: utilizar ou divulgar, indevidamente, com o fim de beneficiar a si ou a outrem, ou de comprometer a credibilidade do certame, conteúdo sigiloso de concurso público; avaliação ou exame públicos; processo seletivo para ingresso no ensino superior; ou exame ou processo seletivo previstos em lei. Pena: reclusão de 1 a 4 anos e multa. Mesma pena a quem permite ou facilita, por qualquer meio, o acesso de pessoas não autorizadas às informações. Se da ação ou omissão resulta dano à administração pública: reclusão de 2 a 6 anos e multa. Aumenta-se a pena de 1/3 se o fato é cometido por funcionário público.', '["Utilizar ou divulgar indevidamente conteúdo sigiloso de concurso, exame ou processo seletivo.","Fim de beneficiar a si ou a outrem, ou de comprometer a credibilidade do certame.","Reclusão de 1 a 4 anos e multa.","§1º: permitir ou facilitar o acesso de pessoas não autorizadas.","§2º: dano à administração pública: reclusão de 2 a 6 anos e multa.","§3º: funcionário público: aumento de 1/3."]'::jsonb, '["Tema relevante para concursos: a ''cola eletrônica'' e o vazamento de provas."]'::jsonb, 'Servidor divulga o conteúdo sigiloso da prova de um concurso para beneficiar um candidato.', '["Assertiva que dispensa o fim de beneficiar ou de comprometer a credibilidade do certame erra."]'::jsonb, '[]'::jsonb, '["Art. 312"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-311-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Peculato: apropriar-se o funcionário público de dinheiro, valor ou qualquer outro bem móvel, público ou particular, de que tem a posse em razão do cargo, ou desviá-lo, em proveito próprio ou alheio. Pena: reclusão de dois a doze anos e multa. Aplica-se a mesma pena se o funcionário, embora sem a posse, subtrai ou concorre para que seja subtraído o bem, valendo-se da facilidade do cargo (peculato-furto). Peculato culposo: se o funcionário concorre culposamente para o crime de outrem, detenção de três meses a um ano. No peculato culposo, a reparação do dano antes da sentença irrecorrível extingue a punibilidade; se posterior, reduz de metade a pena imposta.', '["Peculato-apropriação: apropriar-se de bem de que tem a posse em razão do cargo.","Peculato-desvio: desviá-lo em proveito próprio ou alheio.","Reclusão de dois a doze anos e multa.","§1º peculato-furto: subtrai ou concorre para que seja subtraído, valendo-se da facilidade do cargo.","§2º culposo: detenção de três meses a um ano.","§3º: reparação do dano antes da sentença irrecorrível extingue a punibilidade (só no culposo)."]'::jsonb, '["Reparação do dano só tem esse efeito no peculato CULPOSO.","No peculato-furto, o agente NÃO tem a posse do bem."]'::jsonb, 'Servidor que tem a guarda de valores públicos se apropria deles.', '["Assertiva que extingue a punibilidade pela reparação do dano no peculato doloso erra: isso vale para o culposo, antes da sentença irrecorrível."]'::jsonb, '[{"termo":"Peculato-furto","significado":"Funcionário sem a posse subtrai bem valendo-se da facilidade do cargo."}]'::jsonb, '["Art. 313","Art. 327"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-312'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Peculato mediante erro de outrem: apropriar-se de dinheiro ou qualquer utilidade que, no exercício do cargo, recebeu por erro de outrem. Pena: reclusão de um a quatro anos e multa.', '["Apropriar-se de dinheiro ou utilidade recebida por erro de outrem.","No exercício do cargo.","Reclusão de um a quatro anos e multa."]'::jsonb, '["Também chamado de peculato-estelionato.","O erro é de TERCEIRO, não do funcionário."]'::jsonb, 'Servidor recebe pagamento indevido por engano do contribuinte e se apropria do valor.', '["Assertiva que exige que o funcionário tenha induzido o erro no art. 313 erra: o erro é de outrem."]'::jsonb, '[]'::jsonb, '["Art. 312"]'::jsonb, 'under_review', 'claude'
