insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Inserção de dados falsos em sistema de informações: inserir ou facilitar, o funcionário autorizado, a inserção de dados falsos, alterar ou excluir indevidamente dados corretos nos sistemas informatizados ou bancos de dados da Administração Pública, com o fim de obter vantagem indevida para si ou para outrem ou para causar dano. Pena: reclusão de 2 a 12 anos e multa.', '["Funcionário AUTORIZADO insere ou facilita inserção de dados falsos, altera ou exclui dados corretos.","Sistemas informatizados ou bancos de dados da Administração Pública.","Fim de obter vantagem indevida ou causar dano.","Reclusão de 2 a 12 anos e multa."]'::jsonb, '["Crime próprio de funcionário autorizado.","Exige dolo específico."]'::jsonb, 'Servidor autorizado altera dados do sistema para beneficiar alguém.', '["Assertiva que dispensa a condição de funcionário autorizado no art. 313-A erra."]'::jsonb, '[]'::jsonb, '["Art. 313-B","Art. 299"]'::jsonb, 'under_review', 'claude'
