insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Extravio, sonegação ou inutilização de livro ou documento: extraviar livro oficial ou qualquer documento, de que tem a guarda em razão do cargo; sonegá-lo ou inutilizá-lo, total ou parcialmente. Pena: reclusão de um a quatro anos, se o fato não constitui crime mais grave.', '["Extraviar, sonegar ou inutilizar livro oficial ou documento sob guarda em razão do cargo.","Reclusão de um a quatro anos.","Subsidiário."]'::jsonb, '["Crime subsidiário.","O agente tem a GUARDA do documento em razão do cargo."]'::jsonb, 'Servidor inutiliza processo que estava sob sua guarda.', '["Assertiva que aplica o art. 314 mesmo havendo crime mais grave erra."]'::jsonb, '[]'::jsonb, '["Art. 337"]'::jsonb, 'under_review', 'claude'
