select u.id, u.content_sha256, 'Emprego irregular de verbas ou rendas públicas: dar às verbas ou rendas públicas aplicação diversa da estabelecida em lei. Pena: detenção de um a três meses, ou multa.', '["Dar às verbas ou rendas públicas aplicação diversa da legal.","Detenção de um a três meses, ou multa."]'::jsonb, '["Não há proveito próprio: a verba é aplicada em outra finalidade pública."]'::jsonb, 'Administrador usa verba da educação para outra finalidade não prevista em lei.', '["Assertiva que exige apropriação da verba no art. 315 erra: há apenas aplicação diversa da legal."]'::jsonb, '[]'::jsonb, '["Art. 312"]'::jsonb, 'under_review', 'claude'
