insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Concussão: exigir, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida. Pena: reclusão de 2 a 12 anos e multa. Excesso de exação (§1º): se o funcionário exige tributo ou contribuição social que sabe ou deveria saber indevido, ou, quando devido, emprega na cobrança meio vexatório ou gravoso que a lei não autoriza: reclusão de 3 a 8 anos e multa. Se o funcionário desvia, em proveito próprio ou de outrem, o que recebeu indevidamente para recolher aos cofres públicos: reclusão de dois a doze anos e multa.', '["Caput: EXIGIR vantagem indevida em razão da função.","Reclusão de 2 a 12 anos e multa.","§1º excesso de exação: exigir tributo indevido ou cobrar de modo vexatório: reclusão de 3 a 8 anos e multa.","§2º: desviar o que recebeu indevidamente para recolher aos cofres públicos."]'::jsonb, '["Concussão = EXIGIR (corrupção passiva = SOLICITAR/RECEBER/ACEITAR).","Pode ser praticada fora da função ou antes de assumi-la, desde que em razão dela."]'::jsonb, 'Fiscal exige dinheiro do contribuinte para não lavrar a autuação.', '["Assertiva que confunde concussão com corrupção passiva erra: concussão exige; corrupção passiva solicita, recebe ou aceita."]'::jsonb, '[{"termo":"Excesso de exação","significado":"Cobrar tributo indevido ou cobrar de modo vexatório ou gravoso."}]'::jsonb, '["Art. 317","Art. 333"]'::jsonb, 'under_review', 'claude'
