on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Corrupção passiva: solicitar ou receber, para si ou para outrem, direta ou indiretamente, ainda que fora da função ou antes de assumi-la, mas em razão dela, vantagem indevida, ou aceitar promessa de tal vantagem. Pena: reclusão de 2 a 12 anos e multa. A pena é aumentada de um terço se, em consequência da vantagem ou promessa, o funcionário retarda ou deixa de praticar qualquer ato de ofício ou o pratica infringindo dever funcional. Se o funcionário pratica, deixa de praticar ou retarda ato de ofício, com infração de dever funcional, cedendo a pedido ou influência de outrem: detenção de três meses a um ano, ou multa.', '["Solicitar, receber ou aceitar promessa de vantagem indevida.","Reclusão de 2 a 12 anos e multa.","§1º: aumento de um terço se o funcionário retarda ou deixa de praticar ato de ofício, ou o pratica infringindo dever funcional.","§2º (privilegiada): cede a pedido ou influência de outrem: detenção de três meses a um ano, ou multa."]'::jsonb, '["Crime formal: consuma-se com a solicitação, recebimento ou aceitação da promessa; o ato de ofício apenas aumenta a pena.","Corrupção passiva é crime próprio de funcionário público (com particulares possíveis em concurso)."]'::jsonb, 'Servidor aceita promessa de dinheiro para agilizar processo.', '["Assertiva que exige a prática do ato de ofício para consumar a corrupção passiva erra: ele só gera o aumento do §1º."]'::jsonb, '[]'::jsonb, '["Art. 316","Art. 333"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-317'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Facilitação de contrabando ou descaminho: facilitar, com infração de dever funcional, a prática de contrabando ou descaminho (art. 334). Pena: reclusão de 3 a 8 anos e multa.', '["Facilitar, com infração de dever funcional, o contrabando ou o descaminho.","Reclusão de 3 a 8 anos e multa."]'::jsonb, '["Exceção à teoria monista: o funcionário responde por crime próprio, e o particular, pelo art. 334."]'::jsonb, 'Agente aduaneiro deixa de fiscalizar para facilitar a entrada irregular de mercadorias.', '["Assertiva que aplica o art. 318 a particular que não infringe dever funcional erra."]'::jsonb, '[]'::jsonb, '["Art. 334","Art. 334-A"]'::jsonb, 'under_review', 'claude'
