insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Prevaricação: retardar ou deixar de praticar, indevidamente, ato de ofício, ou praticá-lo contra disposição expressa de lei, para satisfazer interesse ou sentimento pessoal. Pena: detenção de três meses a um ano e multa.', '["Retardar ou deixar de praticar ato de ofício, ou praticá-lo contra expressa disposição de lei.","Fim de satisfazer interesse ou sentimento pessoal.","Detenção de três meses a um ano e multa."]'::jsonb, '["Exige dolo específico: INTERESSE ou SENTIMENTO PESSOAL.","Não há vantagem indevida (senão seria corrupção)."]'::jsonb, 'Servidor deixa de atender um requerimento por inimizade com o interessado.', '["Assertiva que dispensa o interesse ou sentimento pessoal na prevaricação erra."]'::jsonb, '[]'::jsonb, '["Art. 317","Art. 320"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-319'
