insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Prevaricação em estabelecimento penal: deixar o Diretor de Penitenciária e/ou agente público de cumprir seu dever de vedar ao preso o acesso a aparelho telefônico, de rádio ou similar, que permita a comunicação com outros presos ou com o ambiente externo. Pena: detenção de 3 meses a 1 ano.', '["Diretor de penitenciária ou agente público deixa de vedar ao preso acesso a telefone, rádio ou similar.","Detenção de 3 meses a 1 ano."]'::jsonb, '["Crime omissivo próprio.","A conduta do preso que usa o aparelho é falta grave (Lei de Execução Penal)."]'::jsonb, 'Agente penitenciário permite que o preso mantenha celular na cela.', '["Assertiva que pune o preso que usa celular, por esse artigo, erra: o tipo pune quem deixa de vedar o acesso."]'::jsonb, '[]'::jsonb, '["Art. 349-A"]'::jsonb, 'under_review', 'claude'
