insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Condescendência criminosa: deixar o funcionário, por indulgência, de responsabilizar subordinado que cometeu infração no exercício do cargo ou, quando lhe falte competência, não levar o fato ao conhecimento da autoridade competente. Pena: detenção de quinze dias a um mês, ou multa.', '["Deixar de responsabilizar subordinado por indulgência.","Ou não levar o fato ao conhecimento da autoridade competente, quando faltar competência.","Detenção de quinze dias a um mês, ou multa."]'::jsonb, '["Motivo é a INDULGÊNCIA (tolerância).","O infrator é SUBORDINADO."]'::jsonb, 'Chefe deixa de punir subordinado por pena do colega.', '["Assertiva que exige vantagem indevida na condescendência criminosa erra: o motivo é a indulgência."]'::jsonb, '[]'::jsonb, '["Art. 319"]'::jsonb, 'under_review', 'claude'
