insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Advocacia administrativa: patrocinar, direta ou indiretamente, interesse privado perante a administração pública, valendo-se da qualidade de funcionário. Pena: detenção de um a três meses, ou multa. Se o interesse é ilegítimo: detenção de três meses a um ano, além da multa.', '["Patrocinar interesse privado perante a administração, valendo-se da qualidade de funcionário.","Detenção de um a três meses, ou multa.","Parágrafo único: interesse ilegítimo: detenção de três meses a um ano, além da multa."]'::jsonb, '["Interesse ilegítimo agrava a pena."]'::jsonb, 'Servidor intercede em favor de um conhecido perante outro setor, usando seu cargo.', '["Assertiva que exige que o interesse seja ilegítimo no caput erra: ele agrava a pena no parágrafo único."]'::jsonb, '[]'::jsonb, '["Art. 337-G"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-321'
