insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Violência arbitrária: praticar violência, no exercício de função ou a pretexto de exercê-la. Pena: detenção de seis meses a três anos, além da pena correspondente à violência.', '["Praticar violência no exercício de função ou a pretexto de exercê-la.","Detenção de seis meses a três anos, além da pena da violência."]'::jsonb, '["Hoje o abuso de autoridade é regido pela Lei nº 13.869, de 2019, o que reduz a incidência prática do art. 322."]'::jsonb, 'Funcionário agride alguém a pretexto de cumprir suas funções.', '["Assertiva que absorve a pena da violência no art. 322 erra: a pena é somada."]'::jsonb, '[]'::jsonb, '["Lei nº 13.869, de 2019"]'::jsonb, 'under_review', 'claude'
