insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Abandono de função: abandonar cargo público, fora dos casos permitidos em lei. Pena: detenção de quinze dias a um mês, ou multa. Se resulta prejuízo público: detenção de três meses a um ano e multa. Se ocorre em lugar compreendido na faixa de fronteira: detenção de um a três anos e multa.', '["Abandonar cargo público fora dos casos permitidos em lei.","Detenção de quinze dias a um mês, ou multa.","§1º: prejuízo público: detenção de três meses a um ano e multa.","§2º: faixa de fronteira: detenção de um a três anos e multa."]'::jsonb, '["Faixa de fronteira tem a pena mais alta."]'::jsonb, 'Servidor abandona o cargo na faixa de fronteira.', '["Assertiva que fixa a mesma pena para o caput e a faixa de fronteira erra."]'::jsonb, '[]'::jsonb, '["Art. 324"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-323'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Exercício funcional ilegalmente antecipado ou prolongado: entrar no exercício de função pública antes de satisfeitas as exigências legais, ou continuar a exercê-la, sem autorização, depois de saber oficialmente que foi exonerado, removido, substituído ou suspenso. Pena: detenção de quinze dias a um mês, ou multa.', '["Entrar no exercício da função antes de cumprir as exigências legais.","Continuar a exercê-la, sem autorização, depois de saber oficialmente da exoneração, remoção, substituição ou suspensão.","Detenção de quinze dias a um mês, ou multa."]'::jsonb, '["Exige ciência OFICIAL no caso do exercício prolongado."]'::jsonb, 'Servidor continua trabalhando após ser oficialmente informado de sua exoneração.', '["Assertiva que dispensa a ciência oficial na modalidade prolongada erra."]'::jsonb, '[]'::jsonb, '["Art. 323"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-324'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Violação de sigilo funcional: revelar fato de que tem ciência em razão do cargo e que deva permanecer em segredo, ou facilitar-lhe a revelação. Pena: detenção de seis meses a dois anos, ou multa, se o fato não constitui crime mais grave. Nas mesmas penas quem permite ou facilita, mediante atribuição, fornecimento e empréstimo de senha ou qualquer outra forma, o acesso de pessoas não autorizadas a sistemas de informações ou banco de dados da Administração Pública, ou se utiliza indevidamente do acesso restrito. Se resulta dano à Administração ou a outrem: reclusão de 2 a 6 anos e multa.', '["Revelar fato sigiloso de que tem ciência em razão do cargo, ou facilitar a revelação.","Detenção de seis meses a dois anos, ou multa (subsidiário).","§1º: permitir acesso de pessoas não autorizadas a sistemas, ou usar indevidamente o acesso restrito.","§2º: dano à Administração ou a outrem: reclusão de 2 a 6 anos e multa."]'::jsonb, '["Empréstimo de senha pode configurar o §1º.","Subsidiário no caput."]'::jsonb, 'Servidor empresta sua senha a pessoa não autorizada para acessar o sistema.', '["Assertiva que não pune o servidor que empresta sua senha erra: configura o §1º, I."]'::jsonb, '[]'::jsonb, '["Art. 153","Art. 313-A"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-325'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Violação do sigilo de proposta de concorrência: devassar o sigilo de proposta de concorrência pública, ou proporcionar a terceiro o ensejo de devassá-lo. Pena: detenção de três meses a um ano e multa.', '["Devassar o sigilo de proposta de concorrência pública.","Ou proporcionar a terceiro a oportunidade de devassá-lo.","Detenção de três meses a um ano e multa."]'::jsonb, '["Atenção ao regime de licitações da Lei nº 14.133, de 2021."]'::jsonb, 'Servidor abre propostas lacradas antes do momento e informa um concorrente.', '["Assertiva que aplica o art. 326 a qualquer sigilo funcional erra: o tipo trata do sigilo de proposta de concorrência pública."]'::jsonb, '[]'::jsonb, '["Art. 325"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-326'
