insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Conceito de funcionário público: considera-se funcionário público, para os efeitos penais, quem, embora transitoriamente ou sem remuneração, exerce cargo, emprego ou função pública. Equipara-se a funcionário público quem exerce cargo, emprego ou função em entidade paraestatal, e quem trabalha para empresa prestadora de serviço contratada ou conveniada para a execução de atividade típica da Administração Pública. A pena será aumentada da terça parte quando os autores dos crimes deste Capítulo forem ocupantes de cargos em comissão ou de função de direção ou assessoramento de órgão da administração direta, sociedade de economia mista, empresa pública ou fundação instituída pelo poder público.', '["Funcionário público: quem exerce cargo, emprego ou função pública, ainda que transitoriamente ou sem remuneração.","§1º: equiparados (paraestatal; empresa contratada para atividade típica da Administração).","§2º: aumento da terça parte para cargos em comissão ou função de direção ou assessoramento."]'::jsonb, '["Conceito AMPLO: transitoriedade e ausência de remuneração não afastam.","O aumento de terça parte aplica-se aos crimes DESTE Capítulo."]'::jsonb, 'Mesário voluntário em eleição pode ser considerado funcionário público para fins penais.', '["Assertiva que exige remuneração para ser funcionário público para fins penais erra: basta exercer, ainda que sem remuneração."]'::jsonb, '[{"termo":"Entidade paraestatal","significado":"Entidade que atua ao lado do Estado em atividades de interesse público."}]'::jsonb, '["Art. 312","Art. 317"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-327'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Usurpação de função pública: usurpar o exercício de função pública. Pena: detenção de três meses a dois anos e multa. Se o agente aufere vantagem: reclusão de dois a cinco anos e multa.', '["Usurpar o exercício de função pública.","Detenção de três meses a dois anos e multa.","Parágrafo único: vantagem auferida: reclusão de dois a cinco anos e multa."]'::jsonb, '["O usurpador é PARTICULAR (não é funcionário)."]'::jsonb, 'Particular se passa por fiscal e exerce atos de fiscalização.', '["Assertiva que considera o usurpador funcionário público erra: ele exerce função pública sem ter cargo."]'::jsonb, '[]'::jsonb, '["Art. 324"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-328'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Resistência: opor-se à execução de ato legal, mediante violência ou ameaça a funcionário competente para executá-lo ou a quem lhe esteja prestando auxílio. Pena: detenção de dois meses a dois anos. Se o ato, em razão da resistência, não se executa: reclusão de um a três anos. As penas são aplicáveis sem prejuízo das correspondentes à violência.', '["Opor-se à execução de ato legal mediante violência ou ameaça.","Detenção de dois meses a dois anos.","§1º: o ato não se executa: reclusão de um a três anos.","§2º: sem prejuízo da pena da violência."]'::jsonb, '["O ato deve ser LEGAL.","Exige violência ou ameaça (sem elas, pode ser desobediência)."]'::jsonb, 'Ameaçar o oficial de justiça para impedir o cumprimento de mandado legal.', '["Assertiva que configura resistência sem violência ou ameaça erra: seria desobediência, se cabível."]'::jsonb, '[]'::jsonb, '["Art. 330"]'::jsonb, 'under_review', 'claude'
