insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Desobediência: desobedecer a ordem legal de funcionário público. Pena: detenção de quinze dias a seis meses e multa.', '["Desobedecer a ordem LEGAL de funcionário público.","Detenção de quinze dias a seis meses e multa."]'::jsonb, '["A ordem deve ser legal e emanada de funcionário público competente.","Sem violência ou ameaça."]'::jsonb, 'Particular descumpre ordem legal de autoridade, sem violência.', '["Assertiva que configura desobediência pela recusa de ordem ilegal erra: a ordem deve ser legal."]'::jsonb, '[]'::jsonb, '["Art. 329"]'::jsonb, 'under_review', 'claude'
