insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Desacato: desacatar funcionário público no exercício da função ou em razão dela. Pena: detenção de seis meses a dois anos, ou multa.', '["Desacatar funcionário público.","No exercício da função ou em razão dela.","Detenção de seis meses a dois anos, ou multa."]'::jsonb, '["Exige relação com a função."]'::jsonb, 'Ofender policial durante a abordagem.', '["Assertiva que dispensa a relação com a função pública no desacato erra."]'::jsonb, '[]'::jsonb, '["Art. 330"]'::jsonb, 'under_review', 'claude'
