insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Tráfico de influência: solicitar, exigir, cobrar ou obter, para si ou para outrem, vantagem ou promessa de vantagem, a pretexto de influir em ato praticado por funcionário público no exercício da função. Pena: reclusão de 2 a 5 anos e multa. A pena é aumentada da metade, se o agente alega ou insinua que a vantagem é também destinada ao funcionário.', '["Solicitar, exigir, cobrar ou obter vantagem a pretexto de influir em ato de funcionário público.","Reclusão de 2 a 5 anos e multa.","Parágrafo único: alegar ou insinuar que a vantagem também se destina ao funcionário: aumento da metade."]'::jsonb, '["O agente apenas ALEGA ter influência."]'::jsonb, 'Pessoa cobra dinheiro dizendo ter influência para destravar um processo.', '["Assertiva que exige que o agente seja funcionário público no art. 332 erra: o crime é comum."]'::jsonb, '[]'::jsonb, '["Art. 357","Art. 317"]'::jsonb, 'under_review', 'claude'
