insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Corrupção ativa: oferecer ou prometer vantagem indevida a funcionário público, para determiná-lo a praticar, omitir ou retardar ato de ofício. Pena: reclusão de 2 a 12 anos e multa. A pena é aumentada de um terço, se, em razão da vantagem ou promessa, o funcionário retarda ou omite ato de ofício, ou o pratica infringindo dever funcional.', '["Oferecer ou prometer vantagem indevida a funcionário público.","Fim de determiná-lo a praticar, omitir ou retardar ato de ofício.","Reclusão de 2 a 12 anos e multa.","Parágrafo único: aumento de um terço se o funcionário retarda, omite ou pratica o ato infringindo dever funcional."]'::jsonb, '["Núcleos do tipo: OFERECER e PROMETER (não há ''dar'' no caput).","Crime formal."]'::jsonb, 'Particular oferece dinheiro ao fiscal para que deixe de autuá-lo.', '["Assertiva que exige a aceitação da vantagem pelo funcionário na corrupção ativa erra: o crime se consuma com o oferecimento ou a promessa."]'::jsonb, '[]'::jsonb, '["Art. 317"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-333'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Descaminho: iludir, no todo ou em parte, o pagamento de direito ou imposto devido pela entrada, pela saída ou pelo consumo de mercadoria. Pena: reclusão de 1 a 4 anos. Incorre na mesma pena quem pratica navegação de cabotagem fora dos casos permitidos em lei; pratica fato assimilado, em lei especial, a descaminho; vende, expõe à venda, mantém em depósito ou utiliza, no exercício de atividade comercial ou industrial, mercadoria de procedência estrangeira que introduziu clandestinamente no País ou importou fraudulentamente, ou que sabe ser produto de introdução clandestina ou de importação fraudulenta por parte de outrem; adquire, recebe ou oculta, no exercício de atividade comercial ou industrial, mercadoria de procedência estrangeira, desacompanhada de documentação legal ou acompanhada de documentos que sabe serem falsos.', '["Iludir, total ou parcialmente, o pagamento de direito ou imposto devido pela entrada, saída ou consumo de mercadoria.","Reclusão de 1 a 4 anos.","§1º: cabotagem irregular; fato assimilado; venda e utilização de mercadoria estrangeira clandestina; aquisição sem documentação legal."]'::jsonb, '["Descaminho: mercadoria PERMITIDA, com fraude no pagamento do imposto.","Contrabando (art. 334-A): mercadoria PROIBIDA."]'::jsonb, 'Trazer do exterior mercadorias permitidas sem pagar o imposto devido.', '["Assertiva que confunde descaminho com contrabando erra: descaminho envolve mercadoria permitida; contrabando, proibida."]'::jsonb, '[{"termo":"Descaminho","significado":"Fraude no pagamento do imposto devido em mercadoria permitida."}]'::jsonb, '["Art. 334-A","Art. 318"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-334'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Contrabando: importar ou exportar mercadoria proibida. Pena: reclusão de 2 a 5 anos. Incorre na mesma pena quem pratica fato assimilado, em lei especial, a contrabando; importa ou exporta clandestinamente mercadoria que dependa de registro, análise ou autorização de órgão público competente; reinsere no território nacional mercadoria brasileira destinada à exportação; vende, expõe à venda, mantém em depósito ou utiliza, no exercício de atividade comercial ou industrial, mercadoria proibida pela lei brasileira; adquire, recebe ou oculta, em proveito próprio ou alheio, no exercício de atividade comercial ou industrial, mercadoria proibida. Equipara-se às atividades comerciais qualquer forma de comércio irregular ou clandestino de mercadorias estrangeiras, inclusive o exercido em residências, entre outras previsões do dispositivo.', '["Importar ou exportar mercadoria PROIBIDA.","Reclusão de 2 a 5 anos.","§1º: fato assimilado; mercadoria dependente de autorização; reinserção de mercadoria destinada à exportação; venda, utilização e aquisição de mercadoria proibida.","§2º: equipara-se às atividades comerciais o comércio irregular ou clandestino de mercadorias estrangeiras."]'::jsonb, '["Contrabando = mercadoria PROIBIDA; descaminho = fraude fiscal em mercadoria permitida."]'::jsonb, 'Importar mercadoria que a lei brasileira proíbe.', '["Assertiva que fixa pena de detenção para o contrabando erra: é reclusão de 2 a 5 anos."]'::jsonb, '[]'::jsonb, '["Art. 334"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-penal' and u.unit_key = 'art-334-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

